const s=$input.first().json;
const allowedProjects=new Set(['P1_FLOW_INTEGRITY','P2_AGILE_DELIVERY','P3_CONTROL_VALUE','P4_ATTESTOR']);
const allowedDomains=new Set(['FLOW_INTEGRITY','AGILE_DELIVERY','CONTROL_VALUE','ATTESTOR_COMMITMENT_ASSURANCE','ATTESTOR_SERVICE_RECOVERY','ATTESTOR_CUSTOMER_MOMENTUM']);
const required=['sourceProject','sourceDomain','sourceRecordId','sourceSchemaVersion','observedAt','entityKey','outcomeKey','status','severity','evidenceRefs','provenance','authoritativeFields'];
const errors=[];
for(const x of s.signals){
  for(const k of required){ if(x[k]===undefined || x[k]===null || x[k]==='') errors.push(`${x.sourceRecordId||'UNKNOWN'}:missing:${k}`); }
  if(!allowedProjects.has(x.sourceProject)) errors.push(`${x.sourceRecordId}:unknown_project`);
  if(!allowedDomains.has(x.sourceDomain)) errors.push(`${x.sourceRecordId}:unknown_domain`);
  if(!Array.isArray(x.evidenceRefs)||!x.evidenceRefs.length) errors.push(`${x.sourceRecordId}:missing_evidence_refs`);
  if(!x.provenance?.repository||!x.provenance?.artifactPath||!x.provenance?.evidenceClass) errors.push(`${x.sourceRecordId}:invalid_provenance`);
  if(!Array.isArray(x.authoritativeFields)||!x.authoritativeFields.length) errors.push(`${x.sourceRecordId}:missing_authoritative_fields`);
}
s.sourceContract={valid:errors.length===0,errors};
s.audit.push({step:'SOURCE_CONTRACT',valid:errors.length===0,errorCount:errors.length});
if(errors.length) throw new Error('SYNTHESIS_SOURCE_CONTRACT_FAILED:'+errors.join('|'));
return [{json:s}];

const s=$input.first().json;
s.normalizedSignals=s.signals.map(x=>({
  ...x,
  sourceProject:String(x.sourceProject),
  sourceDomain:String(x.sourceDomain),
  sourceRecordId:String(x.sourceRecordId),
  entityKey:String(x.entityKey),
  outcomeKey:String(x.outcomeKey),
  controlKey:x.controlKey?String(x.controlKey):null,
  claimKey:x.claimKey?String(x.claimKey):null,
  evidenceRefs:[...new Set(x.evidenceRefs.map(String))].sort(),
  authoritativeFields:[...new Set(x.authoritativeFields.map(String))].sort()
}));
s.audit.push({step:'NORMALIZE',signalCount:s.normalizedSignals.length});
return [{json:s}];

const s=$input.first().json;
const errors=[];
const now=new Date('2026-08-09T12:00:00Z').getTime();
for(const x of s.normalizedSignals){
  const ts=Date.parse(x.observedAt);
  if(!Number.isFinite(ts)) errors.push(`${x.sourceRecordId}:bad_timestamp`);
  if(x.provenance.evidenceClass!=='SYNTHETIC_FIXTURE') errors.push(`${x.sourceRecordId}:unexpected_fixture_evidence_class`);
  if(x.evidenceRefs.some(r=>!/^EVD-/.test(r))) errors.push(`${x.sourceRecordId}:bad_evidence_ref`);
  if(now-ts>1000*60*60*24*7) errors.push(`${x.sourceRecordId}:stale_evidence`);
}
s.evidenceGate={valid:errors.length===0,errors};
s.audit.push({step:'EVIDENCE_GATE',valid:errors.length===0,errorCount:errors.length});
if(errors.length) throw new Error('SYNTHESIS_EVIDENCE_GATE_FAILED:'+errors.join('|'));
return [{json:s}];

const s=$input.first().json;
const sig=s.normalizedSignals;
const candidates=[];
function add(id,recordIds){candidates.push({candidateId:id,sourceRecordIds:recordIds});}
const p1=sig.find(x=>x.sourceRecordId==='P1-FI-001');
const p1d=sig.find(x=>x.sourceRecordId==='P1-FI-001-DUP');
const p2a=sig.find(x=>x.sourceRecordId==='P2-AD-101');
const p2b=sig.find(x=>x.sourceRecordId==='P2-AD-102');
const p3=sig.find(x=>x.sourceRecordId==='P3-CV-201');
const p4ca=sig.find(x=>x.sourceRecordId==='P4-CA-301');
const p4cm=sig.find(x=>x.sourceRecordId==='P4-CM-302');
const p4sr=sig.find(x=>x.sourceRecordId==='P4-SR-401');
add('CAND-DUP',[p1.sourceRecordId,p1d.sourceRecordId]);
add('CAND-REP',[p2a.sourceRecordId,p2b.sourceRecordId]);
add('CAND-REL',[p1.sourceRecordId,p2a.sourceRecordId]);
add('CAND-CMP',[p1.sourceRecordId,p2a.sourceRecordId,p3.sourceRecordId,p4cm.sourceRecordId]);
add('CAND-CON',[p3.sourceRecordId,p4ca.sourceRecordId]);
add('CAND-UNR',[p4sr.sourceRecordId]);
s.candidates=candidates;
s.audit.push({step:'GENERATE_CANDIDATES',candidateCount:candidates.length});
return [{json:s}];

const s=$input.first().json;
const byId=Object.fromEntries(s.normalizedSignals.map(x=>[x.sourceRecordId,x]));
const out=[];
const routeFor={duplicate:'NO_ACTION_DUPLICATE',repeated:'OBSERVE_REPEATED',related:'OBSERVE_RELATED',compounding:'HUMAN_REVIEW_COMPOUNDING',contradictory:'HUMAN_REVIEW_CONTRADICTION',unresolved:'REQUEST_MORE_EVIDENCE'};
for(const c of s.candidates){
  const xs=c.sourceRecordIds.map(id=>byId[id]);
  let cls='unresolved',reason='Insufficient evidence for a stronger correlation class.';
  const fps=xs.map(x=>x.evidenceFingerprint).filter(Boolean);
  const sameEntity=xs.every(x=>x.entityKey===xs[0].entityKey);
  const sameOutcome=xs.every(x=>x.outcomeKey===xs[0].outcomeKey);
  const projects=new Set(xs.map(x=>x.sourceProject));
  const claims=xs.filter(x=>x.claimKey);
  const sameClaim=claims.length>=2 && claims.every(x=>x.claimKey===claims[0].claimKey);
  const claimVals=new Set(claims.map(x=>JSON.stringify(x.claimValue)));
  const sameControl=xs.length>=2 && xs.every(x=>x.controlKey===xs[0].controlKey);
  const negativeStates=xs.filter(x=>/BLOCK|NOT_VERIFIED|DETERIORAT|OPEN_/i.test(x.status)).length;

  if(xs.length>=2 && fps.length===xs.length && new Set(fps).size===1){
    cls='duplicate'; reason='Distinct source records carry the same evidence fingerprint.';
  } else if(xs.length>=2 && sameEntity && sameOutcome && sameControl && xs.every(x=>x.sourceProject===xs[0].sourceProject)){
    cls='repeated'; reason='The same source project recorded the same control condition more than once for the same entity/outcome.';
  } else if(sameClaim && claimVals.size>1){
    cls='contradictory'; reason='Authoritative source signals assert different values for the same claim key.';
  } else if(xs.length>=3 && sameEntity && sameOutcome && projects.size>=3 && negativeStates>=3){
    cls='compounding'; reason='Three or more source projects contribute unresolved/negative signals to the same entity and outcome.';
  } else if(xs.length>=2 && sameEntity && sameOutcome && projects.size>=2){
    cls='related'; reason='Different source projects reference the same entity and outcome without meeting duplicate, contradiction or compounding rules.';
  }

  out.push({
    correlationId:'COR-'+String(out.length+1).padStart(3,'0'),
    class:cls,
    entityKey:xs[0].entityKey,
    outcomeKey:xs[0].outcomeKey,
    sourceRecordIds:xs.map(x=>x.sourceRecordId),
    sourceProjects:[...new Set(xs.map(x=>x.sourceProject))].sort(),
    evidenceRefs:[...new Set(xs.flatMap(x=>x.evidenceRefs))].sort(),
    deterministicReason:reason,
    sourceAuthorityPreserved:true,
    route:routeFor[cls]
  });
}
s.correlations=out;
s.audit.push({step:'CLASSIFY_CORRELATIONS',classes:out.map(x=>x.class)});
return [{json:s}];

const s=$input.first().json;
const expected=['duplicate','repeated','related','compounding','contradictory','unresolved'];
const got=s.correlations.map(x=>x.class);
const errors=[];
for(const c of s.correlations){
  if(!expected.includes(c.class)) errors.push(`${c.correlationId}:bad_class`);
  if(!c.sourceAuthorityPreserved) errors.push(`${c.correlationId}:source_authority_not_preserved`);
  if(!c.evidenceRefs?.length) errors.push(`${c.correlationId}:missing_evidence`);
}
for(const k of expected){ if(!got.includes(k)) errors.push(`taxonomy_missing:${k}`); }
s.correlationValidation={valid:errors.length===0,errors};
s.audit.push({step:'VALIDATE_CORRELATIONS',valid:errors.length===0});
if(errors.length) throw new Error('SYNTHESIS_CORRELATION_VALIDATION_FAILED:'+errors.join('|'));
return [{json:s}];

const s=$input.first().json;
s.aiExplanations=s.correlations.map(c=>({
  correlationId:c.correlationId,
  explanation:`${c.class.toUpperCase()}: ${c.deterministicReason}`,
  evidenceRefsUsed:[...c.evidenceRefs],
  limitations:['Synthetic Portfolio Preview fixture','Source facts remain authoritative'],
  proposedNarrativeRoute:c.route
}));
s.audit.push({step:'AI_EXPLANATION_REPLAY',synthetic:true,count:s.aiExplanations.length});
return [{json:s}];

const s=$input.first().json;
const corr=Object.fromEntries(s.correlations.map(x=>[x.correlationId,x]));
s.aiCritique=s.aiExplanations.map(a=>{
  const c=corr[a.correlationId];
  const known=new Set(c.evidenceRefs);
  const invented=a.evidenceRefsUsed.filter(x=>!known.has(x));
  return {
    correlationId:a.correlationId,
    unsupportedClaimFlag:false,
    inventedEvidenceFlag:invented.length>0,
    sourceAuthorityOverrideFlag:false,
    routeOverrideFlag:a.proposedNarrativeRoute!==c.route,
    critiqueNotes:invented.length?'Unknown evidence reference found.':'Narrative remains within deterministic correlation boundary.'
  };
});
s.audit.push({step:'AI_CRITIQUE_REPLAY',synthetic:true,count:s.aiCritique.length});
return [{json:s}];

const s=$input.first().json;
