const s=$input.first().json;
const classes=new Set(s.correlations.map(x=>x.class));
let route='OBSERVE';
if(classes.has('contradictory')) route='HUMAN_REVIEW_CONTRADICTION';
else if(classes.has('compounding')) route='HUMAN_REVIEW_COMPOUNDING';
else if(classes.has('unresolved')) route='REQUEST_MORE_EVIDENCE';
s.executiveRoute=route;
s.audit.push({step:'DETERMINISTIC_EXECUTIVE_ROUTE',route});
return [{json:s}];

