const s=$input.first().json;
const allowed=new Set(s.humanDecisionRequest.allowedDecisions);
const validCorrelation=new Set(s.correlations.map(x=>x.correlationId));
const knownEvidence=new Set(s.humanDecisionRequest.evidenceRefs);
const errors=[];
if(!allowed.has(s.humanDecision.decision)) errors.push('decision_not_allowed');
if(!validCorrelation.has(s.humanDecision.correlationId)) errors.push('correlation_mismatch');
if(!s.humanDecision.decidedBy) errors.push('decidedBy_missing');
if(!Date.parse(s.humanDecision.decidedAt)) errors.push('decidedAt_invalid');
for(const e of s.humanDecision.evidenceRefs){ if(!knownEvidence.has(e)) errors.push('unknown_decision_evidence:'+e); }
s.humanDecisionValidation={valid:errors.length===0,errors,authenticatedIdentity:false};
s.audit.push({step:'VALIDATE_HUMAN_DECISION',valid:errors.length===0,authenticatedIdentity:false});
if(errors.length) throw new Error('SYNTHESIS_HUMAN_DECISION_FAILED:'+errors.join('|'));
return [{json:s}];

const s=$input.first().json;
const units=s.correlations.length;
const opportunitiesPerUnit=5;
let defects=0;
for(const c of s.correlations){
  if(!c.sourceRecordIds.length) defects++;
  if(!c.evidenceRefs.length) defects++;
  if(!c.sourceAuthorityPreserved) defects++;
  if(!c.deterministicReason) defects++;
  if(!c.route) defects++;
}
const opportunities=units*opportunitiesPerUnit;
s.measurement={
  syntheticMeasurement:true,
  unit:'validated correlation record',
  defectDefinitions:[
    'missing source binding',
    'missing evidence binding',
    'source authority not preserved',
    'missing deterministic reason',
    'missing deterministic route'
  ],
  opportunitiesPerUnit,
  units,
  defects,
  opportunities,
  dpmo:opportunities?Number((defects/opportunities*1000000).toFixed(2)):null,
  capabilityClaim:false,
  note:'Synthetic fixture measurement only. DPMO is not evidence of process capability; no Sigma or Cpk claim is made.'
};
s.audit.push({step:'SIX_SIGMA_SYNTHESIS_ROLLUP',units,defects,opportunities});
return [{json:s}];

const s=$input.first().json;
s.finalAudit={
  sourceProjects:[...new Set(s.normalizedSignals.map(x=>x.sourceProject))].sort(),
  sourceDomains:[...new Set(s.normalizedSignals.map(x=>x.sourceDomain))].sort(),
  taxonomyClasses:[...new Set(s.correlations.map(x=>x.class))].sort(),
  sourceAuthorityPreserved:s.correlations.every(x=>x.sourceAuthorityPreserved),
  aiValidated:s.aiValidation.valid,
  humanDecisionValidated:s.humanDecisionValidation.valid,
  productionEvidence:false
};
s.audit.push({step:'FINAL_AUDIT',...s.finalAudit});
return [{json:s}];

